"use strict";

// The rows ARE the requirement: what a meal added at an hour is called.
const TABLE = {
  columns: ["Added at", "Called"],
  rows: [
    ["04:00 to 11:00", "breakfast"],
    ["11:00 to 16:00", "lunch"],
    ["16:00 to 22:00", "dinner"],
    ["22:00 to 04:00", "a late bite"],
    ["An hour whose meal the day already has", "a snack"],
  ],
};

const at = (h, m = 0) => h * 60 + m;

module.exports = {
  description: "a meal added is named for the time of day, and for what the day already has",
  table: TABLE,
  async verify(assert) {
    const { mealAt } = await import("../../../../site/planNG/lib/days.js");
    assert.equal(mealAt(at(8)), "breakfast");
    assert.equal(mealAt(at(10, 55)), "breakfast");
    assert.equal(mealAt(at(11)), "lunch");
    assert.equal(mealAt(at(15, 55)), "lunch");
    assert.equal(mealAt(at(16)), "dinner");
    assert.equal(mealAt(at(21, 55)), "dinner");
    assert.equal(mealAt(at(22)), "late");
    assert.equal(mealAt(at(25)), "late", "past midnight on the same night is still late");
    assert.equal(mealAt(at(13), ["lunch"]), "snack", "a second lunch is a snack");
    assert.equal(mealAt(at(13), ["dinner"]), "lunch", "another meal the day has does not matter");
  },
};
"use strict";
const { jerusalemReady, routeFares, flightsSettled, answerTravel, moveTripEnd } = require("../../shared/case-helpers");

/* The fares are asked for the trip's own days and route, once each way, and
 * again for the one day that moved; a fare links to its own page on the
 * partner's site. */
module.exports = {
  description: "fares are asked for the trip's days and route when they are set, and a flight links to that fare on the partner's site",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    const asked = await routeFares(page);
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);
    assert.equal(asked.length, 0, "nothing is asked before the reader says they are flying");

    await answerTravel(page, { home: "GB", way: "fly" });
    await flightsSettled(page);
    const q = (p) => [p.get("from"), p.get("to"), p.get("date"), p.get("currency")];
    assert.deepEqual(
      asked.map(q),
      [
        ["LON", "TLV", "2026-10-17", "gbp"],
        ["TLV", "LON", "2026-10-23", "gbp"],
      ],
      "London to Ben Gurion on the trip's first day, and back on its last, in pounds"
    );
    assert.equal(
      await page.getAttribute(".flight--out .flight-fare", "href"),
      "https://www.aviasales.com/search/LON1710TLV1?t=LY17606769001776066300000290LHRTLV_d4e5f6&search_date=24092026&expected_price_uuid=00000000-0000-0000-0000-000000000002&expected_price_source=share&expected_price_currency=gbp",
      "the cheapest fare out links to its own page"
    );

    await moveTripEnd(page, "to", "2026-10-24");
    await page.waitForFunction(() => document.querySelector(".flight--back .flight-day")?.textContent.includes("24"));
    await flightsSettled(page);
    assert.deepEqual(asked.slice(2).map(q), [["TLV", "LON", "2026-10-24", "gbp"]], "a moved last day asks again for that day only");

    await page.fill("#flightFrom", "par");
    await page.dispatchEvent("#flightFrom", "change");
    await flightsSettled(page);
    assert.deepEqual(
      asked.slice(3).map((p) => [p.get("from"), p.get("to")]),
      [
        ["PAR", "TLV"],
        ["TLV", "PAR"],
      ],
      "a typed airport asks again both ways"
    );
  },
};
- `28.8` A meal added is named for the time of day, and for what that day already has.

  <table><thead><tr><th align="left">Added at</th><th align="left">Called</th></tr></thead><tbody><tr><td>04:00 to 11:00</td><td>breakfast</td></tr><tr><td>11:00 to 16:00</td><td>lunch</td></tr><tr><td>16:00 to 22:00</td><td>dinner</td></tr><tr><td>22:00 to 04:00</td><td>a late bite</td></tr><tr><td>An hour whose meal the day already has</td><td>a snack</td></tr></tbody></table> <!-- req-gallery:28.8 -->

  <details><summary>Notes</summary>

  The hours are the table's; a day that already has that meal gets a snack
  instead, so a second click at lunchtime does not make a second lunch.

- `28.9` A flight's block in the calendar asks how you get between the airport and town: a taxi or transfer, the train, or a hire car, each with where to book it.

