new=anchor+'''
/* ---- the checkout: the locked shows, gathered to buy ------------------- */
.checkout {
  margin-top: 18px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
}
.checkout-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.checkout-title {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
}
.checkout-count {
  margin: 0;
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 600;
}
.checkout-groups {
  display: grid;
  gap: 14px;
  margin: 12px 0;
}
.checkout-festival {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  font-size: 0.9rem;
  font-weight: 700;
}
.checkout-how {
  margin: 2px 0 6px;
  color: var(--muted);
  font-size: 0.78rem;
}
.checkout-how a {
  color: inherit;
}
.checkout-list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.checkout-row {
  display: grid;
  grid-template-columns: 110px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 6px 0;
  border-top: 1px solid var(--line);
  font-size: 0.85rem;
}
.checkout-when {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.checkout-show {
  overflow: hidden;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.checkout-buy {
  color: var(--violet-dark);
  font-size: 0.78rem;
  font-weight: 700;
}
.checkout-buy--free,
.checkout-buy--covered {
  color: var(--muted);
}
.checkout-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
}
.checkout-go {
