8	 *
9	 * Pure: no DOM, no fetch.
10	 */
11	
12	/* What each way of selling asks the checkout to open. `perShow`: every show
13	 * that is not free is bought on its own page. Otherwise one page, the
14	 * festival's ticketing url, covers the festival, unless nothing is sold. */
15	export const TICKETING_MODELS = {
16	  "central-box-office": { perShow: true, sellsTickets: true },
17	  "per-event-seller": { perShow: true, sellsTickets: true },
18	  "festival-pass": { perShow: false, sellsTickets: true },
19	  "all-free": { perShow: false, sellsTickets: false },
20	  "other": { perShow: false, sellsTickets: true },
21	};
22	
23	/* A festival that has not said, or names a way this page does not know yet,
24	 * is sent to its own site: the page can always say that much truthfully. */
25	const UNKNOWN = { perShow: false, sellsTickets: true };
26	
27	/** How a festival's registry entry sells its tickets; `model` is null where it
28	 * has not said or names a way this page does not know. */
29	export function ticketingOf(festival) {
30	  const model = festival && festival.ticketing ? festival.ticketing.model : null;
31	  return { model: TICKETING_MODELS[model] ? model : null, ...(TICKETING_MODELS[model] || UNKNOWN) };
32	}
33	
34	/**
35	 * The checkout for a set of locked shows.
36	 * @param {{slug, festivalId, title, date, start, ticketUrl, url, free}[]} items
37	 *   one per locked show, at its locked performance
38	 * @param {(id: string) => object|null} festivalById the registry entry for a festival id
39	 * @returns {{groups: {festivalId, model, items: {…, destination: string|null}[]}[],
40	 *   destinations: {url: string, festivalId: string, slugs: string[]}[]}}
41	 *   `destination` is where that show is bought, null when it needs no ticket
42	 *   or the festival's one page covers it; `destinations` is every place to
43	 *   open, once each, in the order the shows play.
44	 */
45	export function checkoutPlan(items, festivalById) {
46	  const sorted = [...items].sort(
47	    (a, b) => `${a.date}T${a.start}`.localeCompare(`${b.date}T${b.start}`) || a.slug.localeCompare(b.slug)
...
50	  const open = (url, festivalId, slug) => {
51	    if (!destinations.has(url)) destinations.set(url, { url, festivalId, slugs: [] });
52	    destinations.get(url).slugs.push(slug);
53	  };
54	  for (const item of sorted) {
55	    const festival = festivalById(item.festivalId);
56	    const how = ticketingOf(festival);
57	    if (!groups.has(item.festivalId)) {
