"use strict";
const { plannerReady } = require("../../shared/case-helpers");

/* The Haifa trip reaches Acco: the day given to Acco, which holds free shows,
 * beside the Haifa day before it. */
module.exports = {
  description: "a show's block carries its festival's colour, its kind's emoji and, when free, a Free tag",
  page: "/planNG/?festival=haifa-iff",
  viewport: "desktop",
  ready: (page) => plannerReady(page, "haifa-iff"),
  async capture(page, t) {
    const date = await page.$$eval(".sch-day", (cols) => {
      const free = cols.find((col) => col.querySelector(".sch-free"));
      return free ? free.dataset.date : null;
    });
    if (!date) throw new Error("no day holds a free show");
    const cols = await page.$$eval(".sch-day", (els) => els.map((el) => el.dataset.date));
    const pair = [cols[cols.indexOf(date) - 1], date].map((d) => `.sch-day[data-date="${d}"] .sch-body`);
    return t.clip(t.pad(t.union(await Promise.all(pair.map((sel) => t.rectOf(sel)))), 4));
  },
};
"use strict";
const { plannerReady } = require("../../shared/case-helpers");

module.exports = {
  description: "under the calendar, a legend names each festival with a show in view, in its colour",
  page: "/planNG/?festival=haifa-iff",
  viewport: "desktop",
  ready: (page) => plannerReady(page, "haifa-iff"),
  capture: "#festLegend",
};
"use strict";
const { openOthers, jerusalemReady } = require("../../shared/case-helpers");

const EDINBURGH_KEYS = ["edfringe.plan.favourites.v1", "edfringe.plan.prefs.v1"];

/** Which show is drafted at a given night and hour, or null. */
function draftedAt(page, date, time) {
  return page.evaluate(
    ([d, t]) => {
      const block = [...document.querySelectorAll(`.sch-day[data-date="${d}"] .sch-show`)].find(
        (b) => b.dataset.key.endsWith(`T${t}`)
      );
      return block ? block.dataset.slug : null;
    },
    [date, time]
  );
}

module.exports = {
  description: "the four verdicts survive a reload, under the festival's own storage prefix",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
    await jerusalemReady(page);

    // Two verdicts that pull in opposite directions, so a reload that dropped
    // either would be visible: one show refused outright, and a contender
    // locked into the hour the draft had given to someone else.
    const refusedNight = "2026-10-20";
    const refused = await draftedAt(page, refusedNight, "20:00");
    assert.ok(refused, "the programme drafts something into the contested hour");
    // The verdicts live in the popup the card opens, not on the card itself.
